package io.heapy.komok.tech.runtime.wrappers

/**
 * Times each call to the annotated `suspend` method, tagging success/failure. [name]
 * defaults to `"<owner>.<method>"`. Generated by the Komok runtime compiler plugin into a
 * produced-value decorator; no reflection.
 *
 * The wrapper context is not static: an annotated method must declare
 * `context(_: MeterRegistry)` (after the `@Log` context parameter, if any), and the
 * caller provides the registry at the call site.
 *
 * Middle of the production wrapper chain: `@Log` -> `@Metric` -> `@Retry` -> delegate, so
 * the metric measures the full latency including retries.
 */
@io.heapy.komok.tech.runtime.CallWrapper("io.heapy.komok.tech.runtime.wrappers.metricCall", 200)
@Target(AnnotationTarget.FUNCTION, AnnotationTarget.CLASS)
@Retention(AnnotationRetention.BINARY)
annotation class Metric(
    val name: String = "",
)
